# Local Store's front door for Dify: one address for its web app, its API,
# its collaboration socket and plugin webhooks. Written for Local Store rather
# than rendered from Dify's templates, because nothing here varies by install.

server {
    listen 80;
    server_name _;
    # Docker's own resolver, so nginx starts before the services it names do.
    resolver 127.0.0.11 valid=30s ipv6=off;
    client_max_body_size 100M;
    keepalive_timeout 65;

    location ~ ^/(console/api|api|v1|openapi|files|mcp|triggers) {
        set $api dify-api:5001;
        proxy_pass http://$api;
        proxy_http_version 1.1;
        proxy_set_header Host $http_host;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Connection "";
        proxy_buffering off;
        proxy_read_timeout 3600s;
        proxy_send_timeout 3600s;
    }

    location /socket.io/ {
        set $socket dify-api-websocket:5001;
        proxy_pass http://$socket;
        proxy_http_version 1.1;
        proxy_set_header Host $http_host;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_buffering off;
        proxy_read_timeout 3600s;
        proxy_send_timeout 3600s;
    }

    location /e/ {
        set $plugins dify-plugin-daemon:5002;
        proxy_pass http://$plugins;
        proxy_http_version 1.1;
        proxy_set_header Host $http_host;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Connection "";
        proxy_set_header Dify-Hook-Url $scheme://$http_host$request_uri;
        proxy_buffering off;
        proxy_read_timeout 3600s;
        proxy_send_timeout 3600s;
    }

    location / {
        set $web dify-web:3000;
        proxy_pass http://$web;
        proxy_http_version 1.1;
        proxy_set_header Host $http_host;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Connection "";
        proxy_buffering off;
        proxy_read_timeout 3600s;
        proxy_send_timeout 3600s;
    }
}
